-- Assertions for docs/proposals/0066 (rolled back). Business units, metric links, revenue ledger with duplicate and
-- refund protection, verified imports, touchpoints, experiments with method-bound evidence strength, improvement
-- proposals with admin approval and task conversion, permanence and organization isolation.
do $$
declare
  uo uuid := gen_random_uuid(); um uuid := gen_random_uuid(); uv uuid := gen_random_uuid(); ux uuid := gen_random_uuid();
  o uuid; w uuid; o2 uuid; w2 uuid; cmp uuid; cmp2 uuid; met uuid; un uuid; un2 uuid; s1 uuid; s2 uuid; se uuid; ri uuid; tp uuid; ex uuid; ex2 uuid; ex3 uuid; ex4 uuid; pr uuid; pr2 uuid;
  k1 uuid := gen_random_uuid(); k2 uuid := gen_random_uuid(); r jsonb; st text; n int; pf text := 'rollback-fixture-only';
  pass int := 0; fail int := 0; failures text := '';
begin
  execute $t$CREATE OR REPLACE FUNCTION public.verify_ai_accounting(_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $b$ BEGIN IF _proof IS DISTINCT FROM 'rollback-fixture-only' THEN RAISE EXCEPTION 'server accounting verification required'; END IF; END $b$ $t$;
  insert into auth.users(id,email,aud,role,instance_id) values
    (uo,'bi-owner@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000'),
    (um,'bi-member@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000'),
    (uv,'bi-viewer@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000'),
    (ux,'bi-outsider@test.local','authenticated','authenticated','00000000-0000-0000-0000-000000000000');
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uo,'role','authenticated')::text, true); execute 'set local role authenticated';
  o := public.create_organization('BI fixture','B'); select id into w from public.workspaces where org_id = o;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',ux,'role','authenticated')::text, true); execute 'set local role authenticated';
  o2 := public.create_organization('Other BI org','X'); select id into w2 from public.workspaces where org_id = o2;
  execute 'reset role';
  insert into public.organization_members(org_id,user_id,role) values(o,um,'member'),(o,uv,'viewer');
  insert into public.workspace_members(workspace_id,user_id,role) values(w,um,'member'),(w,uv,'viewer');
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uo,'role','authenticated')::text, true); execute 'set local role authenticated';
  insert into public.campaigns(org_id,workspace_id,title,created_by) values(o,w,'Spring search',uo) returning id into cmp;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',ux,'role','authenticated')::text, true); execute 'set local role authenticated';
  insert into public.campaigns(org_id,workspace_id,title,created_by) values(o2,w2,'Other org campaign',ux) returning id into cmp2;
  -- business units: admin only, idempotent by name, invisible to other organizations
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.create_business_unit(w,'brand','Member brand',null); fail:=fail+1; failures:=failures||' member_unit'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uo,'role','authenticated')::text, true); execute 'set local role authenticated';
  r := public.create_business_unit(w,'brand','North',null); un := (r->>'unit_id')::uuid;
  r := public.create_business_unit(w,'brand','north',null);
  if r->>'status'='existing' then pass:=pass+1; else fail:=fail+1; failures:=failures||' unit_idempotent:'||coalesce((r)::text,'?'); end if;
  r := public.create_business_unit(w,'unit','Retail',un); un2 := (r->>'unit_id')::uuid;
  begin perform public.create_business_unit(w,'unit','Bad parent',gen_random_uuid()); fail:=fail+1; failures:=failures||' unit_bad_parent'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',ux,'role','authenticated')::text, true); execute 'set local role authenticated';
  select count(*) into n from public.business_units where workspace_id=w;
  if n=0 then pass:=pass+1; else fail:=fail+1; failures:=failures||' outsider_units:'||coalesce((n)::text,'?'); end if;
  begin perform public.create_business_unit(w,'brand','Hijack',null); fail:=fail+1; failures:=failures||' outsider_unit'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  -- metric links: category/channel/campaign/unit, same-workspace only
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  r := public.define_metric(w,'ad_spend','Ad spend','currency','EUR','decrease',null,null); met := (r->>'metric_id')::uuid;
  perform public.update_metric_definition(met, jsonb_build_object('category','marketing','channel','search','campaign_id',cmp,'unit_id',un));
  select category||':'||channel||':'||(campaign_id=cmp)::text||':'||(unit_id=un)::text into st from public.metric_definitions where id=met;
  if st='marketing:search:true:true' then pass:=pass+1; else fail:=fail+1; failures:=failures||' metric_links:'||coalesce((st)::text,'?'); end if;
  begin perform public.update_metric_definition(met, jsonb_build_object('campaign_id',cmp2)); fail:=fail+1; failures:=failures||' metric_cross_campaign'; exception when others then if sqlerrm ilike '%foreign key%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' metric_cross_campaign_msg '||sqlerrm; end if; end;
  begin perform public.update_metric_definition(met, jsonb_build_object('category','vanity')); fail:=fail+1; failures:=failures||' metric_bad_category'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  -- revenue ledger
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uv,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',100,'EUR',now(),'manual','','',null,null,null,''); fail:=fail+1; failures:=failures||' viewer_sale'; exception when others then if sqlerrm ilike '%Workspace unavailable%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' viewer_sale_msg '||sqlerrm; end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  r := public.record_revenue_event(w,k1,'sale',100,'eur',now()-interval '2 days','manual','INV-1','cust-7',null,null,un,''); s1 := (r->>'event_id')::uuid;
  if r->>'status'='created' then pass:=pass+1; else fail:=fail+1; failures:=failures||' sale_created:'||coalesce((r)::text,'?'); end if;
  r := public.record_revenue_event(w,k1,'sale',100,'EUR',now()-interval '2 days','manual','INV-1','cust-7',null,null,un,'');
  if r->>'status'='existing' and (r->>'event_id')::uuid=s1 then pass:=pass+1; else fail:=fail+1; failures:=failures||' sale_idempotent:'||coalesce((r)::text,'?'); end if;
  begin perform public.record_revenue_event(w,k1,'sale',999,'EUR',now(),'manual','','',null,null,null,''); fail:=fail+1; failures:=failures||' request_reuse'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',100,'EUR',now(),'manual','INV-1','',null,null,null,''); fail:=fail+1; failures:=failures||' duplicate_source_ref'; exception when others then if sqlerrm ilike '%never counted twice%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' duplicate_source_ref_msg '||sqlerrm; end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',100,'EUR',now(),'imported','','',null,null,null,''); fail:=fail+1; failures:=failures||' manual_cannot_import'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',100,'EUR',now()+interval '5 days','manual','','',null,null,null,''); fail:=fail+1; failures:=failures||' future_sale'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',-5,'EUR',now(),'manual','','',null,null,null,''); fail:=fail+1; failures:=failures||' negative_sale'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'sale',5,'EUR',now(),'manual','','jan@example.com',null,null,null,''); fail:=fail+1; failures:=failures||' email_customer_ref'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  r := public.record_revenue_event(w,gen_random_uuid(),'refund',-30,'EUR',now()-interval '1 day','manual','RF-1','',null,s1,null,''); ri := (r->>'event_id')::uuid;
  select unit_id into st from public.revenue_events where id=ri;
  if st=un::text then pass:=pass+1; else fail:=fail+1; failures:=failures||' refund_inherits_unit:'||coalesce((st)::text,'?'); end if;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'refund',-80,'EUR',now(),'manual','','',null,s1,null,''); fail:=fail+1; failures:=failures||' refund_exceeds_sale'; exception when others then if sqlerrm ilike '%cannot exceed%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' refund_exceeds_sale_msg '||sqlerrm; end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'refund',-10,'USD',now(),'manual','','',null,s1,null,''); fail:=fail+1; failures:=failures||' refund_other_currency'; exception when others then if sqlerrm ilike '%currency of its sale%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' refund_other_currency_msg '||sqlerrm; end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'refund',10,'EUR',now(),'manual','','',null,s1,null,''); fail:=fail+1; failures:=failures||' positive_refund'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'correction',-5,'EUR',now(),'manual','','',null,ri,null,''); fail:=fail+1; failures:=failures||' correction_of_refund'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  perform public.record_revenue_event(w,gen_random_uuid(),'cancellation',-70,'EUR',now(),'manual','','',null,s1,null,'');
  begin perform public.record_revenue_event(w,gen_random_uuid(),'refund',-1,'EUR',now(),'manual','','',null,s1,null,''); fail:=fail+1; failures:=failures||' refund_after_full_cancel'; exception when others then if sqlerrm ilike '%cannot exceed%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' refund_after_full_cancel_msg '||sqlerrm; end if; end;
  r := public.record_revenue_event(w,gen_random_uuid(),'sale',500,'USD',now()-interval '3 days','estimated','','',null,null,null,''); se := (r->>'event_id')::uuid;
  begin perform public.record_revenue_event(w,gen_random_uuid(),'refund',-10,'USD',now(),'manual','','',null,se,null,''); fail:=fail+1; failures:=failures||' manual_refund_of_estimate'; exception when others then if sqlerrm ilike '%cannot correct each other%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' manual_refund_of_estimate_msg '||sqlerrm; end if; end;
  begin insert into public.revenue_events(org_id,workspace_id,kind,amount,currency,occurred_at,data_class,source,request_key) values(o,w,'sale',1,'EUR',now(),'manual','manual',gen_random_uuid()); fail:=fail+1; failures:=failures||' direct_insert'; exception when others then if sqlerrm ilike '%permission denied%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' direct_insert_msg '||sqlerrm; end if; end;
  begin update public.revenue_events set amount=1 where id=s1; fail:=fail+1; failures:=failures||' direct_update'; exception when others then if sqlerrm ilike '%permission denied%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' direct_update_msg '||sqlerrm; end if; end;
  execute 'reset role';
  begin update public.revenue_events set note='x' where id=s1; fail:=fail+1; failures:=failures||' ledger_permanent'; exception when others then if sqlerrm ilike '%permanent history%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' ledger_permanent_msg '||sqlerrm; end if; end;
  begin delete from public.revenue_events where id=ri; fail:=fail+1; failures:=failures||' ledger_no_delete'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  -- verified imports: proof, connected source, source reference, no double counting
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uo,'role','authenticated')::text, true); execute 'set local role authenticated';
  perform public.connect_simulated_integration(w,'sim.stripe',array['read'],'healthy');
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','ch_1','',null,'wrong'); fail:=fail+1; failures:=failures||' import_without_proof'; exception when others then if sqlerrm ilike '%server accounting verification%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_without_proof_msg '||sqlerrm; end if; end;
  begin perform public.import_revenue_event_verified(w,'stripe',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','ch_1','',null,pf); fail:=fail+1; failures:=failures||' import_not_connected'; exception when others then if sqlerrm ilike '%not connected%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_not_connected_msg '||sqlerrm; end if; end;
  begin perform public.import_revenue_event_verified(w,'sim.google_ads',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','ch_1','',null,pf); fail:=fail+1; failures:=failures||' import_wrong_source'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','','',null,pf); fail:=fail+1; failures:=failures||' import_without_ref'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  r := public.import_revenue_event_verified(w,'sim.stripe',k2,'sale',40,'EUR',date_trunc('day', now())-interval '1 day','ch_1','cus_1',null,pf); s2 := (r->>'event_id')::uuid;
  r := public.import_revenue_event_verified(w,'sim.stripe',k2,'sale',40,'EUR',date_trunc('day', now())-interval '1 day','ch_1','cus_1',null,pf);
  if r->>'status'='existing' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_retry_existing:'||coalesce((r)::text,'?'); end if;
  begin perform public.import_revenue_event_verified(w,'sim.stripe',k2,'sale',40,'EUR',date_trunc('day', now())-interval '2 days','ch_1','cus_1',null,pf); fail:=fail+1; failures:=failures||' import_key_reuse_other_date'; exception when others then if sqlerrm ilike '%already used for a different entry%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_key_reuse_msg '||sqlerrm; end if; end;
  select data_class||':'||source into st from public.revenue_events where id=s2;
  if st='imported:sim.stripe' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_class:'||coalesce((st)::text,'?'); end if;
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','ch_1','cus_1',null,pf); fail:=fail+1; failures:=failures||' import_duplicate_ref'; exception when others then if sqlerrm ilike '%never counted twice%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_duplicate_ref_msg '||sqlerrm; end if; end;
  r := public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'refund',-15,'EUR',now(),'re_1','cus_1','ch_1',pf);
  if r->>'status'='created' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_refund:'||coalesce((r)::text,'?'); end if;
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'refund',-15,'EUR',now(),'re_2','cus_1','ch_missing',pf); fail:=fail+1; failures:=failures||' import_refund_unknown_sale'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',ux,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'sale',40,'EUR',now(),'ch_9','',null,pf); fail:=fail+1; failures:=failures||' outsider_import'; exception when others then if sqlerrm ilike '%Workspace unavailable%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' outsider_import_msg '||sqlerrm; end if; end;
  select count(*) into n from public.revenue_events where workspace_id=w;
  if n=0 then pass:=pass+1; else fail:=fail+1; failures:=failures||' outsider_revenue:'||coalesce((n)::text,'?'); end if;
  -- touchpoints
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  r := public.record_touchpoint(s1,gen_random_uuid(),cmp,null,'search',now()-interval '5 days'); tp := (r->>'touchpoint_id')::uuid;
  if tp is not null then pass:=pass+1; else fail:=fail+1; failures:=failures||' touch_created:'||coalesce((r)::text,'?'); end if;
  begin perform public.record_touchpoint(s1,gen_random_uuid(),cmp,null,'search',now()-interval '5 days'); fail:=fail+1; failures:=failures||' touch_duplicate'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_touchpoint(s1,gen_random_uuid(),cmp,null,'search',now()); fail:=fail+1; failures:=failures||' touch_after_sale'; exception when others then if sqlerrm ilike '%before the sale%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' touch_after_sale_msg '||sqlerrm; end if; end;
  begin perform public.record_touchpoint(ri,gen_random_uuid(),cmp,null,'search',now()-interval '5 days'); fail:=fail+1; failures:=failures||' touch_on_refund'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.record_touchpoint(s1,gen_random_uuid(),cmp2,null,'search',now()-interval '4 days'); fail:=fail+1; failures:=failures||' touch_cross_campaign'; exception when others then if sqlerrm ilike '%foreign key%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' touch_cross_campaign_msg '||sqlerrm; end if; end;
  begin perform public.record_touchpoint(s1,gen_random_uuid(),null,null,'',now()-interval '4 days'); fail:=fail+1; failures:=failures||' touch_without_target'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  begin perform public.import_touchpoint_verified(s2,gen_random_uuid(),cmp,null,'search',now()-interval '2 days','manual','sim.stripe','x',pf); fail:=fail+1; failures:=failures||' import_touch_manual_evidence'; exception when others then if sqlstate in ('P0001','42501','23514','23505','23503') then pass:=pass+1; else fail:=fail+1; failures:=failures||' unexpected:'||sqlstate||':'||left(sqlerrm,60); end if; end;
  r := public.import_touchpoint_verified(s2,gen_random_uuid(),cmp,null,'search',now()-interval '2 days','verified_link','sim.stripe','meta_cmp',pf);
  if r->>'status'='created' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_touch:'||coalesce((r)::text,'?'); end if;
  -- without the read permission, imports are refused
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uo,'role','authenticated')::text, true); execute 'set local role authenticated';
  perform public.set_integration_levels((select id from public.connector_connections where workspace_id=w and connector_key='sim.stripe'), '{}');
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.import_revenue_event_verified(w,'sim.stripe',gen_random_uuid(),'sale',40,'EUR',now()-interval '1 day','ch_77','',null,pf); fail:=fail+1; failures:=failures||' import_without_read'; exception when others then if sqlerrm ilike '%Read permission%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_without_read_msg '||sqlerrm; end if; end;
  begin perform public.import_touchpoint_verified(s2,gen_random_uuid(),cmp,null,'search',now()-interval '3 days','verified_link','sim.stripe','meta_2',pf); fail:=fail+1; failures:=failures||' import_touch_without_read'; exception when others then if sqlerrm ilike '%Read permission%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' import_touch_without_read_msg '||sqlerrm; end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',uv,'role','authenticated')::text, true); execute 'set local role authenticated';
  begin perform public.import_touchpoint_verified(s2,gen_random_uuid(),cmp,null,'search',now()-interval '3 days','verified_link','sim.stripe','meta_3',pf); fail:=fail+1; failures:=failures||' viewer_import_touch'; exception when others then if sqlerrm ilike '%Sale unavailable%' then pass:=pass+1; else fail:=fail+1; failures:=failures||' viewer_import_touch_msg '||sqlerrm; end if; end;
  execute 'reset role'; perform set_config('request.jwt.claims', json_build_object('sub',um,'role','authenticated')::text, true); execute 'set local role authenticated';
